const body = $input.first().json;

const errors = [];
const required = ["first_name","last_name","email","job_title","department","manager_email","start_date","work_mode"];
for (const field of required) {
  if (!body[field] || body[field].toString().trim() === "") {
    errors.push(`Missing required field: ${field}`);
  }
}

// Email regex
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (body.personal_email && !emailRegex.test(body.personal_email)) {
  errors.push("Invalid personal_email format");
}
if (body.manager_email && !emailRegex.test(body.manager_email)) {
  errors.push("Invalid manager_email format");
}

// Start date must be in the future
if (body.start_date) {
  const startDate = new Date(body.start_date);
  const now = new Date();
  const minDate = new Date(now.getTime() + (3 * 24 * 60 * 60 * 1000)); // 3 days from now
  if (startDate < minDate) {
    errors.push("start_date must be at least 3 business days in the future");
  }
}

// Work mode validation
const validModes = ["remote","hybrid","onsite"];
if (body.work_mode && !validModes.includes(body.work_mode.toLowerCase())) {
  errors.push("work_mode must be one of: remote, hybrid, onsite");
}

if (errors.length > 0) {
  return [{ json: { valid: false, errors, body } }];
}

// Generate codes
const now = new Date();
const year = now.getFullYear();
const random = Math.floor(Math.random() * 9000) + 1000;
const employee_code = `EMP-${year}-${random}`;
const request_code  = `ONB-${year}-${random}`;

return [{
  json: {
    valid: true,
    errors: [],
    employee_code,
    request_code,
    first_name:     body.first_name.trim(),
    last_name:      body.last_name.trim(),
    personal_email: body.email.trim().toLowerCase(),
    job_title:      body.job_title.trim(),
    department:     body.department.trim(),
    manager_email:  body.manager_email.trim().toLowerCase(),
    start_date:     body.start_date,
    work_mode:      body.work_mode.toLowerCase(),
    phone:          body.phone_number || null,
    location:       body.location || "Remote",
    submitted_by:   body.submitted_by || "hr.manager@tanisitech.onmicrosoft.com",
    form_response_id: $('HR Form Intake Webhook').first().json.body.eventId || null,
    intake_data:    body
  }
}];

const deptData = $input.first().json;
const prev = $('Is valid?').first().json;

if (!deptData || !deptData.id) {
  throw new Error(`Department not found: ${prev.department}. Ensure department is one of: Engineering, HR, Finance, Sales, Marketing, IT`);
}

return [{ json: { ...prev, department_id: deptData.id, dept_code: deptData.code } }];

const requestId = $('INSERT onboarding_request').first().json.id;
const employeeId = $('INSERT employee into Supabase').first().json.id;
const startDate = new Date($('INSERT employee into Supabase').first().json.start_date);
const dueDate = new Date(startDate.getTime() - (3 * 24 * 60 * 60 * 1000)); // 3 days before start

// Return items for SplitInBatches or loop
const templates = [
  "Government ID",
  "Signed Offer Letter",
  "Emergency Contact Form",
  "Bank/Payroll Details",
  "Equipment Preference Form",
  "Remote Work Agreement",
  "Data Protection Acknowledgement"
];

return templates.map(name => ({
