    due_date: dueDate.toISOString().split("T")[0],
    status: "pending"
  }
}));

//  TALLY → n8n FIELD MAPPER
//  Insert this Code node BETWEEN:
//    "HR System Webhook"  →  [THIS NODE]  →  "Validate & Mask Payload"
//
//  Handles all Tally field types:
//    DROPDOWN, MULTIPLE_CHOICE, INPUT_TEXT, INPUT_EMAIL,
//    INPUT_DATE, INPUT_NUMBER, TEXTAREA, CHECKBOXES, HIDDEN_FIELDS
// ═══════════════════════════════════════════════════════════════════

const body = $input.first().json.body;

// ── 1. Locate the fields array wherever Tally puts it ─────────────
//    Tally wraps: { eventId, createdAt, data: { fields: [...] } }
//    or sometimes bare:  { fields: [...] }
const fields =
  body?.data?.fields ||
  body?.fields ||
  [];

if (!fields.length) {
  throw new Error('Tally payload has no fields. Check webhook configuration.');
}

// ── 2. Generic field resolver ─────────────────────────────────────
function resolveField(field) {
  const type  = field.type;
  const value = field.value;
  const opts  = field.options || [];

  // No value at all
  if (value === null || value === undefined || value === '') return null;

  switch (type) {

    // Dropdowns & single-choice: value = [uuid]
    // Resolve uuid → text from options array
    case 'DROPDOWN':
    case 'MULTIPLE_CHOICE': {
      if (!Array.isArray(value) || value.length === 0) return null;
      const selectedId = value[0]; // single-select → first element
      const match = opts.find(o => o.id === selectedId);
      return match ? match.text : selectedId; // fallback to raw ID if no match
    }

    // Checkboxes / multi-select: value = [uuid, uuid, ...]
    // Resolve all → array of text labels
    case 'CHECKBOXES': {
      if (!Array.isArray(value) || value.length === 0) return [];
      return value.map(id => {
        const match = opts.find(o => o.id === id);
        return match ? match.text : id;
      });
    }

    // Plain text, email, textarea, number, hidden
    case 'INPUT_TEXT':
    case 'INPUT_EMAIL':
    case 'INPUT_NUMBER':
    case 'TEXTAREA':
    case 'HIDDEN_FIELDS':
    case 'INPUT_PHONE_NUMBER':
      return Array.isArray(value) ? value[0] : value;

    // Date: Tally returns ISO string or { day, month, year }
    case 'INPUT_DATE': {
      if (typeof value === 'string') return value.split('T')[0]; // strip time
      if (value?.year && value?.month && value?.day) {
        const m = String(value.month).padStart(2, '0');
        const d = String(value.day).padStart(2, '0');
        return `${value.year}-${m}-${d}`;
      }
      return String(value);
    }

    // File upload: return the first file URL if present
    case 'FILE_UPLOAD': {
      if (Array.isArray(value) && value.length > 0) {
        return value[0]?.url || value[0] || null;
      }
      return null;
    }

    // Rating / scale: numeric
    case 'LINEAR_SCALE':
    case 'RATING':
      return Number(value);

    // Fallback: return as-is
    default:
      return Array.isArray(value) ? value[0] : value;
  }
}

// ── 3. Build a flat key→value map from ALL fields ─────────────────
//    Uses the field LABEL as the key (lowercased, spaces→underscores)
//    so it's human-readable and survives Tally question ID changes.
const raw = {};
const rawById = {}; // also index by question key (e.g. question_XGpPJe)

for (const field of fields) {
  const resolved = resolveField(field);

  // Label-based key (what we use for mapping)
  if (field.label) {
    const labelKey = field.label
      .toLowerCase()
      .trim()
      .replace(/\s+/g, '_')
      .replace(/[^a-z0-9_]/g, '');
    raw[labelKey] = resolved;
  }

  // ID-based key (fallback)
  if (field.key) {
    rawById[field.key] = resolved;
  }
}

// ── 4. Helper: try multiple label variants for the same field ─────
//    HR teams name fields differently — this makes the mapper robust.
function get(raw, ...candidates) {
  for (const key of candidates) {
    const normalised = key.toLowerCase().replace(/\s+/g, '_').replace(/[^a-z0-9_]/g, '');
    if (raw[normalised] !== undefined && raw[normalised] !== null && raw[normalised] !== '') {
      return raw[normalised];
    }
  }
  return null;
}

// ── 5. Map to the exact shape our workflow expects ─────────────────
const mapped = {
  first_name:   get(raw,
                  'first_name', 'first name', 'given_name', 'given name', 'forename'
                ),

  last_name:    get(raw,
                  'last_name', 'last name', 'surname', 'family_name', 'family name'
                ),

  email:        get(raw,
                  'personal_email', 'personal email', 'email', 'email_address', 'email address',
                  'corporate_email', 'company email'
                ),

  job_title:    get(raw,
                  'job_title', 'job title', 'role', 'position', 'designation',
                  'title', 'role_title'
                ),

  department:   get(raw,
                  'department', 'dept', 'team', 'business_unit', 'business unit',
                  'division'
                ),

  work_mode:  get(raw,
                  'work_mode', 'work mode',
                ) || 'GENERAL',

  start_date:   get(raw,
                  'start_date', 'start date', 'joining_date', 'joining date',
                  'commencement_date', 'employment_start', 'date_of_joining'
                ),

  location:     get(raw,
                  'office_location', 'office location', 'location', 'office',
                  'work_location', 'work location', 'site', 'region'
                ) || 'HQ',

  manager_email:        get(raw,
                  'manager_email', 'manager email', 'direct_manager_email', 'direct manager email'
                ),

  phone_number:    get(raw,
                  'phone_number', 'phone number'
                ),

  note:   get(raw,
                  'additional_notes', 'additional notes', 'notes'
                ),
};

// ── 6. Validation: catch missing critical fields early ─────────────
const critical = ['first_name', 'last_name', 'email', 'job_title', 'department', 'work_mode', 'start_date', 'location', 'manager_email'];
const missing  = critical.filter(f => !mapped[f]);

if (missing.length > 0) {
  // Build a helpful error message showing what we DID receive
  const received = Object.keys(raw).join(', ');
  throw new Error(
    `Tally mapping failed. Missing: [${missing.join(', ')}].\n` +
    `Fields received from Tally: [${received}].\n` +
    `Check that your Tally form field LABELS exactly match expected names, ` +
    `or add the variant to the get() call in the mapper node.`
  );
}

// ── 7. Return mapped payload + debug info ─────────────────────────
return [{
  json: {
    ...mapped,
    _tally_meta: {
      event_id:     body?.eventId || body?.data?.eventId || null,
      submitted_at: body?.createdAt || body?.data?.createdAt || new Date().toISOString(),
      form_id:      body?.formId || body?.data?.formId || null,
      raw_field_keys: Object.keys(raw), // useful for debugging label mismatches
    }
  }
}];

