const tokens = $input.all();
if (!tokens || tokens.length === 0 || !tokens[0].json.id) {
  throw new Error("TOKEN_NOT_FOUND: Invalid token_id");
}
const token = tokens[0].json;
if (token.used) {
  throw new Error("TOKEN_ALREADY_USED: This approval link has already been used.");
}
if (token.revoked) {
  throw new Error("TOKEN_REVOKED: This approval link has been revoked.");
}
if (new Date(token.expires_at) < new Date()) {
  throw new Error("TOKEN_EXPIRED: This approval link has expired. Please check for escalation.");
}
return [{ json: { ...token, action: $('Extract query params').first().json.action } }];

const query = $input.first().json.query || {};
const tokenId = query.token_id;
const action = query.action;

if (!tokenId || !action) {
  throw new Error("Missing token_id or action in request");
}
if (!["approved","rejected"].includes(action)) {
  throw new Error("Invalid action. Must be approved or rejected.");
}
return [{ json: { token_id: tokenId, action } }];

