const stepId = $('INSERT approval_step').first().json.id;
const tokenId = $input.first().json.id;
const n8nBase = $('Prepare approval data').first().json.n8n_base;
const req = $('Fetch request + employee data').first().json.intake_data;
const fullName = $('Fetch request + employee data').first().json.intake_data.first_name + ' ' + $('Fetch request + employee data').first().json.intake_data.last_name

const card = {
  type: "AdaptiveCard",
  "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
  version: "1.4",
  body: [
    {
      type: "TextBlock",
      text: "🧑‍💼 New Hire — HR Approval Required",
      weight: "Bolder",
      size: "Large",
      color: "Accent"
    },
    {
      type: "FactSet",
      facts: [
        { title: "Name",       value: fullName },
        { title: "Role",       value: req.job_title },
        { title: "Start Date", value: req.start_date },
        { title: "Work Mode",  value: req.work_mode },
        { title: "Request",    value: $('Fetch request + employee data').first().json.request_code },
        { title: "Response Due", value: new Date(req.due_at).toLocaleString() }
      ]
    },
    {
      type: "Input.Text",
      id: "note",
      placeholder: "Optional note (required if rejecting)",
      isMultiline: false
    }
  ],
  actions: [
    {
      type: "Action.OpenUrl",
      title: "✅ Approve",
      url: `${n8nBase}/webhook/approval-response?token_id=${tokenId}&action=approved`,
      style: "positive"
    },
    {
      type: "Action.OpenUrl",
      title: "❌ Reject",
      url: `${n8nBase}/webhook/approval-response?token_id=${tokenId}&action=rejected`,
      style: "destructive"
    }
  ]
};

return [{ json: { ...req, card_payload: JSON.stringify(card), step_id: stepId, token_id: tokenId } }];

